Read A2:E8, normalize dates/brands, and find the maximum date for each brand while preserving first-appearance order. Sum quantities for all rows matching each brand's maximum date, taking batch/origin from the first matching row. Write the resulting rows as plain values into H2:L4, clearing any extra answer cells.

```python
import shutil
import openpyxl
from datetime import datetime, date
from openpyxl.utils.datetime import from_excel

def norm_date(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, date):
        return datetime(v.year, v.month, v.day)
    if isinstance(v, (int, float)):
        try:
            return from_excel(v)
        except Exception:
            return None
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y %H:%M:%S", "%d/%m/%Y"):
            try:
                return datetime.strptime(s, fmt)
            except Exception:
                pass
    return None

def norm_text(v):
    if v is None:
        return None
    s = str(v).strip()
    return s if s else None

def norm_qty(v):
    if v is None:
        return 0.0
    if isinstance(v, bool):
        return float(v)
    if isinstance(v, (int, float)):
        return float(v)
    try:
        return float(str(v).strip())
    except Exception:
        return 0.0

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

sheet_name = "ورقة1"
ws = wb[sheet_name]
vws = vals[sheet_name]

records = []
for r in range(2, vws.max_row + 1):
    d = norm_date(vws.cell(r, 1).value)
    brand = norm_text(vws.cell(r, 2).value)
    if d is None or brand is None:
        continue

    batch = norm_text(vws.cell(r, 3).value)
    origin = norm_text(vws.cell(r, 4).value)
    qty = norm_qty(vws.cell(r, 5).value)

    records.append((d, brand, batch, origin, qty))

brand_order = []
max_date = {}

for d, brand, _, _, _ in records:
    if brand not in max_date:
        max_date[brand] = d
        brand_order.append(brand)
    elif d > max_date[brand]:
        max_date[brand] = d

results = []
for brand in brand_order:
    md = max_date[brand]
    total = 0.0
    batch = None
    origin = None

    for d, br, b, o, q in records:
        if br == brand and d == md:
            total += q
            if batch is None:
                batch = b
                origin = o

    if total == int(total):
        total = int(total)

    results.append((md, brand, batch, origin, total))

# Clear the graded answer region first.
for r in range(2, 5):
    for c in range(8, 13):
        ws.cell(row=r, column=c).value = None

# Write computed values into H2:L4.
for i, res in enumerate(results[:3]):
    r = 2 + i
    for j, val in enumerate(res):
        ws.cell(row=r, column=8 + j).value = val

wb.save(OUT)

print("records:", len(records))
print("results:", len(results))
for res in results:
    print(res)
